    ('3193', '7c6980dc0844d36b2bc1a6d6d29a6b01', '{"cl_assigned_to_as_of": "2026-09-30", "cl_assigned_to_evidence_sha256": "5ac1ca14fcb40b7f6069821ccf2871173694a8f07cbf7db8aa6c3cf87dfb2d4c", "cl_assigned_to_id": "2297", "cl_assigned_to_name_as_published": "Kevin Michael Moore", "cl_assigned_to_source_url": null, "judge_cl_person_basis": "judge_profile_native_bridge+cl_docket_assigned_to", "judge_cl_person_id": "2297", "judge_link_basis": "cl_docket_assigned_to", "judge_link_evidence": "cl_docket_assigned_to", "judge_link_exact": true, "judge_link_review": null, "judge_profile_id": "ff1c5f6907dea833c49cebb1bcc103d7"}', '[{"basis": "cl_docket_assigned_to", "cl_person_id": "2297", "display_name": "Kevin Michael Moore", "entity_id": "judge-entity-fc6bd76e81c8c14a9fd26a67", "evidence": "CourtListener docket assigned_to of the master docket -> judge_cl_crosswalk exact_id", "evidence_sha256": "5ac1ca14fcb40b7f6069821ccf2871173694a8f07cbf7db8aa6c3cf87dfb2d4c", "fjc_court": "U.S. District Court for the Southern District of Florida", "fjc_name": "Kevin Michael Moore", "fjc_nid": "1385306", "links": [{"label": "Judge profile", "url": "#judge/ff1c5f6907dea833c49cebb1bcc103d7"}], "match_kind": "first_initial", "name_match_kind": "first_initial"}]', null, 'judge-entity-fc6bd76e81c8c14a9fd26a67')
  ),
t as materialized (
 select r.id, r.item, r.detail, r.filters, v.row_md5, v.patch::jsonb as patch, v.links::jsonb as links, v.cands::jsonb as cands, v.entity,
        (md5(to_jsonb(r)::text) = v.row_md5) as unchanged
 from v join public.corpus_records r on r.dataset = 'mdls' and r.id = v.id),
y as (
 select t.*,
  t.item || t.patch as new_item,
  jsonb_set(t.detail, '{summary}', coalesce(t.detail->'summary', t.item) || t.patch)
    || case when t.links is null then '{}'::jsonb else jsonb_build_object('judge_links', t.links) end
    || case when t.cands is null then '{}'::jsonb else jsonb_build_object('judge_link_candidates', t.cands) end as new_detail,
  t.filters || jsonb_build_object('cl_person_id', coalesce(t.patch->>'judge_cl_person_id', ''),
                                  'entity_id', case when t.entity is null then '[]'::jsonb else jsonb_build_array(t.entity) end)
            || case when t.patch ? 'judge_resolved' then jsonb_build_object('judge_resolved', t.patch->>'judge_resolved') else '{}'::jsonb end as new_filters
 from t),
ins as (
 insert into corpus_ingest.cleanup_decisions (dataset, record_id, issue, disposition, reason, evidence, original_record, replacement, run_id)
 select 'mdls', y.id, 'dejudges20261027_mdls_exact_judge_links', 'label_override',
  'Transferee-judge link re-derived from the CourtListener docket assignment (exact ids); unconfirmed name-variant links kept as needs-review candidates.',
  jsonb_build_object('contract', 'mdls-exact-judge-links/2026-10-27.v1', 'patch', y.patch),
  jsonb_build_object('id', y.id, 'item', y.item, 'detail', y.detail, 'filters', y.filters, 'row_md5', y.row_md5),
  jsonb_build_object('item', y.new_item, 'detail', y.new_detail, 'filters', y.new_filters),
  '7aecb0ac-2c53-5db5-ac4b-20b409868b2c'::uuid
 from y where y.unchanged
 on conflict (dataset, record_id, issue) do nothing
 returning record_id)
select (select count(*) from v) as targets, (select count(*) from t) as found, (select count(*) from t where not unchanged) as changed_since_snapshot,
       (select count(*) from ins) as audit_rows_written;

-- ===== statement 2: apply (mdls records) =====
with u as (
 update public.corpus_records r
    set item = c.replacement->'item', detail = c.replacement->'detail', filters = c.replacement->'filters'
   from corpus_ingest.cleanup_decisions c
  where c.dataset = 'mdls' and c.issue = 'dejudges20261027_mdls_exact_judge_links' and c.run_id = '7aecb0ac-2c53-5db5-ac4b-20b409868b2c'::uuid
    and r.dataset = 'mdls' and r.id = c.record_id and md5(to_jsonb(r)::text) = c.original_record->>'row_md5'
 returning r.id)
select count(*) as updated from u;

-- ===== statement 3: regenerate the mdls metadata copies of item / filters (listing.results, filter_index) and record the run =====
with old as (select d.id, d.metadata from public.corpus_datasets d where d.id = 'mdls' and not (d.metadata ? 'exact_judge_links_2026_10_27')),
live as (select r.id, r.title, r.ordinal, r.item, r.filters from public.corpus_records r where r.dataset = 'mdls'),
oldfi as (select f.value->>'id' as id, f.value->>'search' as search from old, jsonb_array_elements(old.metadata->'filter_index') f),
newres as (select jsonb_agg(l.item order by l.ordinal) as o from live l),
newfacet as (
 select coalesce(jsonb_agg(jsonb_build_array(g.v, g.n) order by g.n desc, g.v), '[]'::jsonb) as o
 from (select l.filters->>'judge_resolved' as v, count(*) as n from live l where coalesce(l.filters->>'judge_resolved', '') <> '' group by 1) g),
newfi as (
 select jsonb_agg(jsonb_build_object('id', l.id, 'item', l.item, 'filters', l.filters,
          'search', coalesce(o.search, lower(l.title) || ' ' || l.id || ' mdl-' || l.id || ' mdl ' || l.id)) order by l.ordinal) as o
 from live l left join oldfi o on o.id = l.id),
aud as (
 insert into corpus_ingest.cleanup_decisions (dataset, record_id, issue, disposition, reason, evidence, original_record, replacement, run_id)
 select 'corpus_datasets', 'mdls', 'dejudges20261027_mdls_exact_judge_links', 'label_override',
  'listing.results and filter_index are exact copies of the live item/filters, and listing.facets.judge_resolved counts the live filters; regenerated after the exact judge links.',
  jsonb_build_object('contract', 'mdls-exact-judge-links/2026-10-27.v1'),
  jsonb_build_object('id', 'mdls', 'listing_results', o.metadata->'listing'->'results', 'filter_index', o.metadata->'filter_index',
                     'listing_facets', o.metadata->'listing'->'facets'), null, '7aecb0ac-2c53-5db5-ac4b-20b409868b2c'::uuid
 from old o on conflict (dataset, record_id, issue) do nothing returning record_id),
upd as (
 update public.corpus_datasets d
    set metadata = jsonb_set(jsonb_set(jsonb_set(o.metadata, '{listing,results}', nr.o), '{filter_index}', nf.o), '{listing,facets,judge_resolved}', fc.o)
                   || jsonb_build_object('exact_judge_links_2026_10_27', '{"contract": "mdls-exact-judge-links/2026-10-27.v1", "linked_after": 146, "linked_after_by_evidence": {"cl_docket_assigned_to": 124, "cl_person_native_bridge": 1, "jpml_exact_name_court": 21}, "linked_before": 172, "linked_before_by_match_kind": {"(none)": 8, "cl_person_native_bridge": 8, "exact": 73, "first_initial": 7, "middle_initial": 76, "middle_omitted": 8}, "live_docket_headers_used": 8, "mdls": 180, "needs_review": {"cl_assigned_to_differs": 5, "cl_assigned_to_unresolved": 4, "name_variant_unconfirmed": 23}, "numeric_master_dockets": 150, "outcomes": {"confirmed": 123, "conflict": 4, "kept_exact": 22, "new": 1, "review": 24, "unlinked": 6}, "recorded_cl_assigned_to_id_differs": [], "run_id": "7aecb0ac-2c53-5db5-ac4b-20b409868b2c", "with_docket_assignment": 139}'::jsonb),
        updated_at = now()
   from old o, newres nr, newfi nf, newfacet fc, aud a
  where d.id = 'mdls'
 returning d.id)
select (select count(*) from aud) as audit_rows, (select count(*) from upd) as datasets_updated;

-- ===== statement 4: audit (judges profile MDL block: remove MDLs that are no longer linked, add new links) =====
with v(profile, mdl, op) as (values
    ('095341e8da8f4a46d90e371f063855aa', '3167', 'drop'),
    ('0ff4c61337c778f70944f5d3513c1000', '3132', 'drop'),
